#!/usr/bin/env python3
"""Ordered high/low reasoning extension of the frozen matched agent pilot."""
import argparse
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import shutil
import signal
import subprocess
import tempfile
import time

ROOT=Path(__file__).resolve().parents[2]
PRIVATE=ROOT/'benchmarks/private-evidence/luna-study-20261123'
BASE=Path(__file__).with_name('study.py')
BASE_REGISTRATION=ROOT/'benchmarks/results/2026-11-23-matched-study-registration-amendment-1.json'
MODEL='gpt-5.6-luna'
EFFORTS=('high','low')

def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def baseline_registration():return json.loads(BASE_REGISTRATION.read_text())
def load_base():
    registration=baseline_registration()
    if sha(BASE)!=registration['harness_sha256']:raise ValueError('frozen base harness changed')
    spec=importlib.util.spec_from_file_location('frozen_matched',BASE)
    module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
    return module

def configure(effort):
    if effort not in EFFORTS:raise ValueError('unregistered reasoning level')
    module=load_base();original=module.command
    def command(folder,row,last):
        args=original(folder,row,last)
        args[args.index('-m')+1]=MODEL
        args=[('model_reasoning_effort="'+effort+'"') if x=='model_reasoning_effort="high"' else x for x in args]
        return args
    module.MODEL=MODEL;module.command=command
    return module

def fixture_hashes(module):
    files={}
    for row in module.schedule():
        values=module.fixtures(row)|{'TASK.txt':module.task_text(row),'GUIDE.txt':module.guide(row['language'])}
        for name,text in values.items():files['%02d/'%row['index']+name]={'sha256':hashlib.sha256(text.encode()).hexdigest(),'bytes':len(text.encode())}
    return files

def infrastructure_failure(result):
    return bool(result['status'] in {'infrastructure_error','agent_error'} or result['grading'].get('infrastructure_error'))

def environment():
    versions=[]
    for command in [['codex','--version'],['rustc','--version'],['clang','--version'],['python3','--version']]:
        process=subprocess.run(command,capture_output=True,text=True,check=True);path=Path(shutil.which(command[0])).resolve()
        versions.append({'command':command,'stdout':process.stdout,'stderr':process.stderr,'executable':str(path),'sha256':sha(path)})
    return {'versions':versions,'logical_cpus':os.cpu_count(),'load':os.getloadavg(),'recorded_unix':time.time()}

def register(out):
    module=load_base();prior=baseline_registration();files=fixture_hashes(module)
    if files!=prior['files']:raise ValueError('task/source/guide content drift')
    freeze=json.loads((module.PRIVATE/'freeze/manifest.json').read_text())
    if any(sha(module.PRIVATE/'freeze'/name)!=value['sha256'] for name,value in freeze['files'].items()):raise ValueError('compiler/source freeze changed')
    catalog_path=Path.home()/'.codex/models_cache.json';catalog=json.loads(catalog_path.read_text());model=next(m for m in catalog['models'] if m['slug']==MODEL)
    if not set(EFFORTS)<={r['effort'] for r in model['supported_reasoning_levels']}:raise ValueError('model does not advertise both reasoning levels')
    manifest={'date':'2026-11-23','format':'lobo-luna-reasoning-study/1','model':MODEL,'ordered_cohorts':list(EFFORTS),'scheduled_per_cohort':54,'scheduled_total':108,'source_commit':prior['source_commit'],'frozen_version':'1.11.2','baseline_registration_sha256':sha(BASE_REGISTRATION),'base_harness_sha256':sha(BASE),'wrapper_sha256':sha(__file__),'input_files':files,'schedule':module.schedule(),'guides':prior['guides'],'limits':{k:prior[k] for k in ['deadline_s','command_tool_items','visible_checks','hard_token_cap']},'environment':environment(),'catalog':{'fetched_at':catalog.get('fetched_at'),'client_version':catalog.get('client_version'),'model':{k:model.get(k) for k in ['slug','description','supported_reasoning_levels','supported_in_api']}},'failure_policy':'Retain every attempt and unknown usage. No retries or replacements. Three consecutive infrastructure failures stop that cohort; proceed to availability check for the next effort. Candidate compile/test/limit failures are ordinary outcomes.','availability_canaries':'One source-free, shell-disabled CLI invocation immediately before each cohort; exclude from scored trials, retain usage. No fallback model.','scope':'Participant CLI invocations only; parent/harness-development usage and billing unknown; no hard token cap','limitations':['Model alias is not immutable weights; older description is not a measured capability ranking','High-before-low order was requested; time/cache/provider drift confounds a causal reasoning comparison','Baseline was measured earlier; equal frozen task bytes and CLI flags do not guarantee identical host instructions or backend behavior','Same three small task families and cued comprehension items as baseline; no task tuning after outcomes']}
    out.mkdir(parents=True,exist_ok=False);module.write_json(out/'manifest.json',manifest)
    return manifest

def canary(module,effort,out):
    out.mkdir(parents=True,exist_ok=False);folder=Path(tempfile.mkdtemp(prefix='luna-availability-'));(folder/'AGENTS.md').write_text('This is a source-free model availability check. Follow the user prompt; do not inspect other directories.\n')
    row={'phase':'comprehension','language':'python'};command=module.command(folder,row,out/'last-message.txt');module.write_json(out/'command.json',command)
    prompt='Model availability check. Use no tools. Reply only READY.';started=time.monotonic();result={'model':MODEL,'reasoning':effort,'excluded_from_scored_trials':True,'command':command}
    env=dict(os.environ);env.pop('CODEX_THREAD_ID',None);env.pop('CODEX_INTERNAL_ORIGINATOR_OVERRIDE',None)
    process=subprocess.Popen(command,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,cwd=folder,env=env,text=True,start_new_session=True)
    timed_out=False
    try:stdout,stderr=process.communicate(prompt,timeout=90)
    except subprocess.TimeoutExpired:
        timed_out=True;os.killpg(process.pid,signal.SIGTERM)
        try:stdout,stderr=process.communicate(timeout=3)
        except subprocess.TimeoutExpired:os.killpg(process.pid,signal.SIGKILL);stdout,stderr=process.communicate()
    (out/'events.jsonl').write_text(stdout);(out/'stderr.txt').write_text(stderr);events=[]
    for line in stdout.splitlines():
        try:events.append(json.loads(line))
        except ValueError:pass
    result.update(exit_code=process.returncode,usage=module.usage(events),available=not timed_out and process.returncode==0 and any(e.get('type')=='turn.completed' for e in events),last_message=(out/'last-message.txt').read_text() if (out/'last-message.txt').exists() else None)
    if timed_out:result['error']='availability timeout; retain reported usage or unknown'
    result['wall_s']=time.monotonic()-started;module.write_json(out/'result.json',result);return result

def run(out,registration_path):
    registration=json.loads(registration_path.read_text());module=load_base()
    if sha(__file__)!=registration['wrapper_sha256'] or fixture_hashes(module)!=registration['input_files']:raise ValueError('registered harness or inputs changed')
    out.mkdir(parents=True,exist_ok=False);overall=[];module.write_json(out/'environment-before.json',environment())
    for effort in registration['ordered_cohorts']:
        module=configure(effort);cohort=out/effort;cohort.mkdir();module.write_json(cohort/'assignment-plan.json',registration['schedule']);results=[]
        print('CANARY',MODEL,effort,flush=True);availability=canary(module,effort,cohort/'availability');module.write_json(cohort/'availability.json',availability)
        if not availability['available']:
            module.write_json(cohort/'results.json',results);module.write_json(cohort/'stopped.json',{'reason':'model/reasoning unavailable; no fallback','remaining':registration['schedule']});overall.append({'reasoning':effort,'attempted':0,'availability':False});module.write_json(out/'progress.json',overall);continue
        streak=0
        for row in registration['schedule']:
            print('START',effort,row,flush=True);result=module.run_trial(row,cohort)
            result['configuration']={'model':MODEL,'reasoning':effort,'base_harness_sha256':registration['base_harness_sha256'],'wrapper_sha256':registration['wrapper_sha256']};module.write_json(cohort/('trial-%02d'%row['index'])/'result.json',result);results.append(result);module.write_json(cohort/'results.json',results)
            print('END',effort,row['index'],result['status'],result['accepted'],result['usage'],flush=True)
            streak=streak+1 if infrastructure_failure(result) else 0
            if streak>=3:
                module.write_json(cohort/'stopped.json',{'reason':'three consecutive infrastructure failures','remaining':registration['schedule'][len(results):]});break
        overall.append({'reasoning':effort,'attempted':len(results),'accepted':sum(r['accepted'] for r in results),'availability':True});module.write_json(out/'progress.json',overall)
    module.write_json(out/'environment-after.json',environment());print('FINISHED',overall,flush=True)

if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('operation',choices=['register','run']);parser.add_argument('--out',type=Path,required=True);parser.add_argument('--registration',type=Path,default=PRIVATE/'registration/manifest.json');args=parser.parse_args()
    if args.operation=='register':register(args.out.resolve())
    else:run(args.out.resolve(),args.registration.resolve())

#!/usr/bin/env python3
"""Report the two requested Luna configurations without changing frozen scoring."""
import argparse
from collections import Counter
import importlib.util
import itertools
import json
from pathlib import Path

HERE=Path(__file__).resolve().parent

def load(name):
    spec=importlib.util.spec_from_file_location(name,HERE/(name+'.py'));module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module);return module

luna=load('luna');base_report=load('report');study=luna.load_base()

def failure_categories(row):
    if row['accepted']:return []
    result=[];grading=row['grading']
    if row['status']!='completed':result.append(row['status'])
    if grading.get('issues'):result.append('scope_rejected')
    if grading.get('infrastructure_error'):result.append('grading_infrastructure_error')
    if grading.get('build') is not None and not grading['build']['ok']:result.append('compile_failed')
    if grading.get('cases') and any(not c['ok'] for c in grading['cases']):result.append('program_observation_failed')
    if 'checks' in grading and not grading['accepted']:result.append('comprehension_items_failed')
    return result or ['other_protocol_failure']

def tokens(row):
    value=row.get('usage')
    return value['input_tokens']+value['output_tokens'] if isinstance(value,dict) and 'input_tokens' in value and 'output_tokens' in value else None

def compare_pairs(left,right):
    lookup={r['assignment']['index']:r for r in right};pairs=[]
    for row in left:
        i=row['assignment']['index'];other=lookup.get(i)
        if other is None:continue
        if row['assignment']!=other['assignment']:raise ValueError('mismatched assignment')
        a,b=tokens(row),tokens(other);wall_left,wall_right=row.get('agent_wall_s'),other.get('agent_wall_s')
        pairs.append({'assignment':row['assignment'],'left_accepted':row['accepted'],'right_accepted':other['accepted'],'left_status':row['status'],'right_status':other['status'],'left_tokens':a,'right_tokens':b,'left_over_right_tokens':a/b if a is not None and b else None,'left_over_right_wall':wall_left/wall_right if wall_left is not None and wall_right else None})
    return pairs

def summarize_pairs(pairs):
    return {'paired_attempts':len(pairs),'both_accepted':sum(p['left_accepted'] and p['right_accepted'] for p in pairs),'only_left_accepted':sum(p['left_accepted'] and not p['right_accepted'] for p in pairs),'only_right_accepted':sum(p['right_accepted'] and not p['left_accepted'] for p in pairs),'neither_accepted':sum(not p['left_accepted'] and not p['right_accepted'] for p in pairs),'reported_token_ratio_known_pairs':base_report.stats([p['left_over_right_tokens'] for p in pairs if p['left_over_right_tokens'] is not None]),'all_attempt_wall_ratio':base_report.stats([p['left_over_right_wall'] for p in pairs if p['left_over_right_wall'] is not None])}

def verify_rows(rows,schedule):
    assignments={r['index']:r for r in schedule};seen=set()
    for row in rows:
        i=row['assignment']['index']
        if i in seen or assignments.get(i)!=row['assignment']:raise ValueError('duplicate/mismatched assignment')
        seen.add(i)
    return [r for r in schedule if r['index'] not in seen]

def publish(out,fixtures_out):
    private=luna.PRIVATE;registration=json.loads((private/'registration/manifest.json').read_text());root=private/'attempts'
    if not (root/'environment-after.json').exists():raise ValueError('wait until both cohorts finish or stop under their registered policy')
    fixtures_out.mkdir(parents=True,exist_ok=False);cohorts=[];all_rows=[];canaries=[];raw_by_config={}
    for effort in registration['ordered_cohorts']:
        folder=root/effort;rows=json.loads((folder/'results.json').read_text());remaining=verify_rows(rows,registration['schedule']);availability=json.loads((folder/'availability.json').read_text());canaries.append(availability);all_rows+=rows;raw_by_config['luna-'+effort]=rows
        destination=fixtures_out/effort;destination.mkdir();attempts=[];manifest=[]
        for row in rows:
            assignment=row['assignment'];i=assignment['index'];trial=folder/('trial-%02d'%i);value=base_report.normalized(row,trial);value['configuration']=row['configuration'];value['failure_categories']=failure_categories(row)
            value['functional_evaluation_status']='scope_rejected' if row['grading'].get('issues') else 'compile_failed' if row['grading'].get('build') and not row['grading']['build']['ok'] else 'evaluated' if row['grading'].get('cases') else 'comprehension' if assignment['phase']=='comprehension' else 'not_evaluated'
            bundle={'configuration':row['configuration'],'assignment':assignment}
            if assignment['phase']=='comprehension':bundle['answer']=(trial/'last-message.txt').read_text() if (trial/'last-message.txt').exists() else None
            else:
                source=trial/'heldout/source';bundle['files']={p.name:p.read_text() for p in source.iterdir() if p.is_file() and p.suffix in {'.lobo','.json','.rs','.py'} and p.name not in {'TASK.txt','GUIDE.txt','check.py','AGENTS.md'}}
            path=destination/('trial-%02d.json'%i);study.write_json(path,bundle);value['public_bundle']=str(path.relative_to(luna.ROOT));value['public_bundle_sha256']=luna.sha(path);manifest.append({'path':value['public_bundle'],'sha256':value['public_bundle_sha256']});attempts.append(value)
        groups=[]
        for phase,language in itertools.product(study.PHASES,study.LANGUAGES):
            subset=[r for r in rows if r['assignment']['phase']==phase and r['assignment']['language']==language];success=[r for r in subset if r['accepted']]
            groups.append({'phase':phase,'language':language,'scheduled':6}|base_report.aggregate(subset)|{'failure_categories':dict(Counter(c for r in subset for c in failure_categories(r))),'successful_only_wall_seconds':base_report.stats([r['agent_wall_s'] for r in success]),'successful_only_reported_tokens':base_report.stats([tokens(r) for r in success if tokens(r) is not None])})
        cohorts.append({'model':luna.MODEL,'reasoning':effort,'scheduled':54,'attempted':len(rows),'accepted':sum(r['accepted'] for r in rows),'unattempted':remaining,'availability':availability,'accounting':base_report.account(rows),'groups':groups,'attempts':attempts,'fixture_manifest':manifest,'failure_categories':dict(Counter(c for r in rows for c in failure_categories(r)))})
    baseline=json.loads((study.PRIVATE/'attempts-amendment-1/results.json').read_text());raw_by_config['sol-high']=baseline;comparisons=[]
    for left,right in [('luna-high','sol-high'),('luna-low','sol-high'),('luna-low','luna-high')]:
        pairs=compare_pairs(raw_by_config[left],raw_by_config[right]);groups=[]
        for phase,language in itertools.product(study.PHASES,study.LANGUAGES):
            subset=[p for p in pairs if p['assignment']['phase']==phase and p['assignment']['language']==language]
            groups.append({'phase':phase,'language':language}|summarize_pairs(subset))
        comparisons.append({'left':left,'right':right,'groups':groups,'pairs':pairs})
    result={'date':'2026-11-23','format':'lobo-luna-reasoning-results/1','registration_sha256':luna.sha(private/'registration/manifest.json'),'baseline_data_sha256':luna.sha(luna.ROOT/'benchmarks/results/2026-11-23-matched-agent-study.json'),'frozen_version':'1.11.2','cohorts':cohorts,'comparisons':comparisons,'all_new_scored_accounting':base_report.account(all_rows),'all_new_participant_and_canary_accounting':base_report.account(all_rows+canaries),'accounting_unit':'CLI agent conversations, each potentially containing multiple underlying model requests; parent/harness development and billing unknown','environment_before':json.loads((root/'environment-before.json').read_text()),'environment_after':json.loads((root/'environment-after.json').read_text()),'limitations':registration['limitations']+['No hard token cap; all-attempt and successful-only costs are separate','Scope rejection can leave functional behavior ungraded; do not label it a proven algorithm defect','Runtime of new generated programs was not benchmarked; older binary timings remain unchanged','Three small task families, two repetitions and multiple descriptive comparisons; no population ranking or causal effect claim']}
    study.write_json(out,result);return result

if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--out',type=Path,required=True);parser.add_argument('--fixtures-out',type=Path,required=True);args=parser.parse_args();publish(args.out.resolve(),args.fixtures_out.resolve())

import importlib.util
import json
from pathlib import Path
import unittest
SPEC=importlib.util.spec_from_file_location('luna',Path(__file__).with_name('matched-study')/'luna.py')
m=importlib.util.module_from_spec(SPEC);SPEC.loader.exec_module(m)
class LunaStudyTests(unittest.TestCase):
 def test_only_model_and_reasoning_change_in_commands(self):
  base=m.load_base()
  for effort in ['high','low']:
   configured=m.configure(effort)
   for phase in base.PHASES:
    row={'phase':phase,'language':'lobo'};old=base.command(Path('/tmp/work'),row,Path('/tmp/last'))
    expected=[m.MODEL if x==base.MODEL else 'model_reasoning_effort="'+effort+'"' if x=='model_reasoning_effort="high"' else x for x in old]
    self.assertEqual(configured.command(Path('/tmp/work'),row,Path('/tmp/last')),expected)
 def test_all_registered_task_source_guide_hashes_are_identical(self):
  module=m.load_base()
  # The registered guide embeds the original compiler path; replay its literal fixture on any checkout.
  baseline=json.loads((m.ROOT/'benchmarks/results/2026-11-23-matched-agent-study.json').read_text())
  candidate=next(r for r in baseline['attempts'] if r['assignment']['language']=='lobo' and r['assignment']['phase']=='construction')
  module.COMPILER=Path(candidate['grading']['build']['command'][0])
  self.assertEqual(m.fixture_hashes(module),m.baseline_registration()['files'])
 def test_compile_and_budget_failure_do_not_trigger_infrastructure_stop(self):
  for status in ['completed','wall_limit','tool_limit']:
   self.assertFalse(m.infrastructure_failure({'status':status,'grading':{'accepted':False}}))
  self.assertTrue(m.infrastructure_failure({'status':'agent_error','grading':{}}))
 def test_invalid_effort_is_rejected(self):
  with self.assertRaises(ValueError):m.configure('minimal')
if __name__=='__main__':unittest.main()

import importlib.util
from pathlib import Path
import unittest
SPEC=importlib.util.spec_from_file_location('luna_report',Path(__file__).with_name('matched-study')/'luna_report.py')
m=importlib.util.module_from_spec(SPEC);SPEC.loader.exec_module(m)
class LunaReportTests(unittest.TestCase):
 def test_failure_categories_do_not_turn_ungraded_scope_into_functional_failure(self):
  row={'status':'completed','accepted':False,'grading':{'issues':['unexpected:test.py'],'build':None,'cases':[]}}
  self.assertEqual(m.failure_categories(row),['scope_rejected'])
  row={'status':'wall_limit','accepted':False,'grading':{'issues':[],'build':{'ok':True},'cases':[{'ok':True}]}}
  self.assertEqual(m.failure_categories(row),['wall_limit'])
 def test_pair_counts_keep_failures_and_unknown_usage(self):
  assignment={'index':0,'family':'ledger','phase':'construction','language':'lobo','repeat':0}
  left={'assignment':assignment,'accepted':False,'status':'wall_limit','usage':None,'agent_wall_s':120}
  right={'assignment':assignment,'accepted':True,'status':'completed','usage':{'input_tokens':10,'output_tokens':5},'agent_wall_s':10}
  pair=m.compare_pairs([left],[right])[0]
  self.assertFalse(pair['left_accepted']);self.assertTrue(pair['right_accepted']);self.assertIsNone(pair['left_over_right_tokens']);self.assertEqual(pair['left_over_right_wall'],12)
if __name__=='__main__':unittest.main()
